/**
 * Since CommandLineRunner.main calls System.exit(-1), we use PowerMock 
 * to prevent the JVM from actually shutting down during the test.
 * We also use MockedConstruction (Mockito 3.5+) or PowerMock to mock the 
 * constructor of CommandLineRunner to control shouldRunCompiler().
 */
@RunWith(PowerMockRunner.class)
@PrepareForTest({CommandLineRunner.class, System.class})
public class CommandLineRunner_main_TriageGen0Test {

    @Test
    public void testMain_ShouldRunCompiler() throws Exception {
        String[] args = {"--some-flag"};

        // Mocking System.exit to prevent actual termination
        PowerMockito.mockStatic(System.class);

        try (MockedConstruction<CommandLineRunner> mocked = mockConstruction(CommandLineRunner.class,
                (mock, context) -> {
                    when(mock.shouldRunCompiler()).thenReturn(true);
                })) {

            CommandLineRunner.main(args);

            CommandLineRunner mockRunner = mocked.constructed().get(0);
            verify(mockRunner).shouldRunCompiler();
            verify(mockRunner).run();

            // Verify System.exit was NOT called
            PowerMockito.verifyStatic(System.class, never());
            System.exit(anyInt());
        }
    }

    @Test
    public void testMain_ShouldExitWhenNotShouldRunCompiler() throws Exception {
        String[] args = {"--some-flag"};

        // Mocking System.exit to prevent actual termination
        PowerMockito.mockStatic(System.class);

        try (MockedConstruction<CommandLineRunner> mocked = mockConstruction(CommandLineRunner.class,
                (mock, context) -> {
                    when(mock.shouldRunCompiler()).thenReturn(false);
                })) {

            CommandLineRunner.main(args);

            CommandLineRunner mockRunner = mocked.constructed().get(0);
            verify(mockRunner).shouldRunCompiler();
            verify(mockRunner, never()).run();

            // Verify System.exit(-1) was called
            PowerMockito.verifyStatic(System.class);
            System.exit(-1);
        }
    }

    @Test
    public void testMain_WithEmptyArgs() throws Exception {
        String[] args = {};

        PowerMockito.mockStatic(System.class);

        try (MockedConstruction<CommandLineRunner> mocked = mockConstruction(CommandLineRunner.class,
                (mock, context) -> {
                    when(mock.shouldRunCompiler()).thenReturn(true);
                })) {

            CommandLineRunner.main(args);

            CommandLineRunner mockRunner = mocked.constructed().get(0);
            verify(mockRunner).shouldRunCompiler();
            verify(mockRunner).run();
        }
    }
}
